<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Bouncing Ball Playground</title>
<style>
  :root {
    --bg: #0f1117;
    --panel: #1a1d29;
    --accent: #6c8dff;
    --accent2: #ff6c8d;
    --text: #e6e8f0;
  }
  * { box-sizing: border-box; }
  html, body {
    height: 100%;
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font-family: 'Segoe UI', system-ui, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 16px;
  }
  h1 {
    font-size: 1.2rem;
    font-weight: 500;
    letter-spacing: 0.05em;
    color: var(--accent);
    margin: 0;
  }
  #stage {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
    padding: 20px;
    background: var(--panel);
    border-radius: 16px;
    box-shadow: 0 10px 40px rgba(0,0,0,0.5);
  }
  #sim {
    background: radial-gradient(circle at 50% 0%, #1c2030, #0b0d13);
    border-radius: 12px;
    cursor: crosshair;
    display: block;
    border: 1px solid #2a2e40;
  }
  #controls {
    display: flex;
    gap: 10px;
  }
  button {
    background: #262a3b;
    color: var(--text);
    border: 1px solid #3a3f56;
    padding: 8px 16px;
    border-radius: 8px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.15s ease, transform 0.1s ease;
  }
  button:hover {
    background: #333850;
  }
  button:active {
    transform: scale(0.95);
  }
  #play.playing {
    background: var(--accent);
    color: #0f1117;
    font-weight: 600;
  }
  #info {
    font-size: 0.75rem;
    color: #8a8fae;
  }
</style>
</head>
<body>
  <h1>BOUNCING BALL PLAYGROUND</h1>
  <div id="stage">
    <canvas id="sim" width="500" height="450"></canvas>
    <div id="controls">
      <button id="drop">Drop Ball</button>
      <button id="play">Play</button>
      <button id="clear">Clear</button>
    </div>
    <div id="info">Click the canvas to drop a ball at the cursor</div>
  </div>

<script>
(function(){
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  const GRAVITY = 0.5;      // acceleration per step
  const RESTITUTION = 0.75; // energy retained on bounce
  const FRICTION = 0.999;   // slight air drag

  const colors = ['#6c8dff', '#ff6c8d', '#6cffb0', '#ffd76c', '#c46cff', '#6cf0ff'];

  let balls = [];
  let playing = true;
  let rafId = null;

  function randColor() {
    return colors[Math.floor(Math.random() * colors.length)];
  }

  function makeBall(x, y, vx = 0, vy = 0, r) {
    if (r === undefined || r === null) {
      r = 12 + Math.random() * 14;
    }
    return {
      x: x, y: y, vx: vx, vy: vy, r: r,
      color: randColor()
    };
  }

  function addBall(x, y, vx = 0, vy = 0, r) {
    // clamp initial position inside canvas so it doesn't spawn out of bounds
    const rr = (r === undefined || r === null) ? 12 + Math.random() * 14 : r;
    const cx = Math.min(Math.max(x, rr), W - rr);
    const cy = Math.min(Math.max(y, rr), H - rr);
    const b = makeBall(cx, cy, vx, vy, rr);
    balls.push(b);
    draw();
    return b;
  }

  function clearBalls() {
    balls.length = 0;
    draw();
  }

  function stepPhysics(dt) {
    if (dt === undefined) dt = 1;
    for (const b of balls) {
      // gravity
      b.vy += GRAVITY * dt;

      // mild drag
      b.vx *= FRICTION;
      b.vy *= FRICTION;

      // integrate
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      // floor
      if (b.y + b.r > H) {
        b.y = H - b.r;
        if (b.vy > 0) b.vy = -b.vy * RESTITUTION;
        if (Math.abs(b.vy) < 0.3) b.vy = 0;
      }
      // ceiling
      if (b.y - b.r < 0) {
        b.y = b.r;
        if (b.vy < 0) b.vy = -b.vy * RESTITUTION;
      }
      // right wall
      if (b.x + b.r > W) {
        b.x = W - b.r;
        if (b.vx > 0) b.vx = -b.vx * RESTITUTION;
      }
      // left wall
      if (b.x - b.r < 0) {
        b.x = b.r;
        if (b.vx < 0) b.vx = -b.vx * RESTITUTION;
      }

      // final safety clamp - never allow tunneling / escape
      if (b.x < b.r) b.x = b.r;
      if (b.x > W - b.r) b.x = W - b.r;
      if (b.y < b.r) b.y = b.r;
      if (b.y > H - b.r) b.y = H - b.r;
    }
    draw();
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    // subtle grid background
    ctx.save();
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    for (let gx = 0; gx < W; gx += 40) {
      ctx.beginPath();
      ctx.moveTo(gx, 0);
      ctx.lineTo(gx, H);
      ctx.stroke();
    }
    for (let gy = 0; gy < H; gy += 40) {
      ctx.beginPath();
      ctx.moveTo(0, gy);
      ctx.lineTo(W, gy);
      ctx.stroke();
    }
    ctx.restore();

    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      const grad = ctx.createRadialGradient(
        b.x - b.r * 0.35, b.y - b.r * 0.35, b.r * 0.1,
        b.x, b.y, b.r
      );
      grad.addColorStop(0, '#ffffff');
      grad.addColorStop(0.25, b.color);
      grad.addColorStop(1, '#00000066');
      ctx.fillStyle = grad;
      ctx.fill();
      ctx.lineWidth = 1.5;
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      ctx.stroke();
    }
  }

  function loop() {
    if (playing) {
      stepPhysics(1);
    }
    rafId = requestAnimationFrame(loop);
  }

  // ---- controls ----
  document.getElementById('drop').addEventListener('click', () => {
    const x = W / 2 + (Math.random() - 0.5) * 60;
    addBall(x, 30, (Math.random() - 0.5) * 6, 0);
  });

  const playBtn = document.getElementById('play');
  function setPlaying(v) {
    playing = v;
    playBtn.textContent = playing ? 'Pause' : 'Play';
    playBtn.classList.toggle('playing', playing);
  }
  playBtn.addEventListener('click', () => setPlaying(!playing));

  document.getElementById('clear').addEventListener('click', () => {
    clearBalls();
  });

  canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = W / rect.width;
    const scaleY = H / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    addBall(x, y, (Math.random() - 0.5) * 4, -2);
  });

  // initial demo balls
  addBall(W * 0.3, H * 0.3, 3, 0);
  addBall(W * 0.6, H * 0.2, -2, 1);

  setPlaying(true);
  loop();

  // ---- required global API ----
  window.sim = {
    w: W,
    h: H,
    balls() {
      return balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r }));
    },
    addBall(x, y, vx = 0, vy = 0, r) {
      const b = addBall(x, y, vx, vy, r);
      return { x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r };
    },
    clear() {
      clearBalls();
    },
    step(dt = 1) {
      stepPhysics(dt);
    }
  };
})();
</script>
</body>
</html>
